def _build_object(value, property_path=None):
    """ Builds the schema definition for an object.

    :param value: The object to build the schema definition for
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :return: The built schema definition
    :rtype: Dict[str, Any]
    """
    properties = {}
    for key, val in value.items():
        properties[key] = _build_type(type(val), val,
                                      property_path=property_path + [key])
    return {'type': 'object', 'properties': properties}


